/**
 * 0/1 Knapsack Problem
 * Time: O(n * W) | Space: O(n * W), optimizable to O(W)
 *
 * Given items with weights and values, find the maximum value
 * that fits within a weight capacity.
 */

// Full DP table approach
function knapsack(weights, values, capacity) {
  const n = weights.length;
  const dp = Array.from({ length: n + 1 }, () =>
    new Array(capacity + 1).fill(0)
  );

  for (let i = 1; i <= n; i++) {
    for (let w = 0; w <= capacity; w++) {
      if (weights[i - 1] <= w) {
        dp[i][w] = Math.max(
          dp[i - 1][w],
          dp[i - 1][w - weights[i - 1]] + values[i - 1]
        );
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  return dp[n][capacity];
}

// Space-optimized (1D array)
function knapsackOptimized(weights, values, capacity) {
  const dp = new Array(capacity + 1).fill(0);

  for (let i = 0; i < weights.length; i++) {
    // Traverse backwards to avoid using same item twice
    for (let w = capacity; w >= weights[i]; w--) {
      dp[w] = Math.max(dp[w], dp[w - weights[i]] + values[i]);
    }
  }

  return dp[capacity];
}

// --- Example ---
const weights = [2, 3, 4, 5];
const values = [3, 4, 5, 6];
const capacity = 8;

console.log(knapsack(weights, values, capacity));          // 10
console.log(knapsackOptimized(weights, values, capacity)); // 10

module.exports = { knapsack, knapsackOptimized };

/**
 * Min Heap / Priority Queue Implementation
 * insert: O(log n) | extractMin: O(log n) | peek: O(1)
 *
 * A complete binary tree where parent <= children.
 * Used in: Dijkstra's, Huffman coding, task scheduling.
 */

class MinHeap {
  constructor() {
    this.heap = [];
  }

  get size() { return this.heap.length; }
  peek() { return this.heap[0]; }
  isEmpty() { return this.heap.length === 0; }

  insert(val) {
    this.heap.push(val);
    this._bubbleUp(this.heap.length - 1);
  }

  extractMin() {
    if (this.isEmpty()) return undefined;
    const min = this.heap[0];
    const last = this.heap.pop();
    if (!this.isEmpty()) {
      this.heap[0] = last;
      this._sinkDown(0);
    }
    return min;
  }

  _bubbleUp(idx) {
    while (idx > 0) {
      const parent = Math.floor((idx - 1) / 2);
      if (this.heap[parent] <= this.heap[idx]) break;
      [this.heap[parent], this.heap[idx]] = [this.heap[idx], this.heap[parent]];
      idx = parent;
    }
  }

  _sinkDown(idx) {
    const n = this.heap.length;
    while (true) {
      let smallest = idx;
      const left = 2 * idx + 1;
      const right = 2 * idx + 2;
      if (left < n && this.heap[left] < this.heap[smallest]) smallest = left;
      if (right < n && this.heap[right] < this.heap[smallest]) smallest = right;
      if (smallest === idx) break;
      [this.heap[smallest], this.heap[idx]] = [this.heap[idx], this.heap[smallest]];
      idx = smallest;
    }
  }
}

// --- Example ---
const pq = new MinHeap();
[5, 3, 8, 1, 2, 7].forEach(v => pq.insert(v));
console.log(pq.extractMin()); // 1
console.log(pq.extractMin()); // 2
console.log(pq.peek());       // 3
console.log(pq.size);         // 4

module.exports = { MinHeap };

/**
 * Trie (Prefix Tree)
 * insert: O(m) | search: O(m) | startsWith: O(m) where m = word length
 *
 * Efficient for autocomplete, spell checking, and prefix-based search.
 */

class TrieNode {
  constructor() {
    this.children = {};
    this.isEndOfWord = false;
    this.count = 0; // Number of words with this prefix
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  insert(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children[char]) {
        node.children[char] = new TrieNode();
      }
      node = node.children[char];
      node.count++;
    }
    node.isEndOfWord = true;
  }

  search(word) {
    const node = this._traverse(word);
    return node !== null && node.isEndOfWord;
  }

  startsWith(prefix) {
    return this._traverse(prefix) !== null;
  }

  // Get all words with a given prefix (autocomplete)
  autocomplete(prefix, maxResults = 10) {
    const node = this._traverse(prefix);
    if (!node) return [];
    const results = [];
    this._dfs(node, prefix, results, maxResults);
    return results;
  }

  _traverse(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children[char]) return null;
      node = node.children[char];
    }
    return node;
  }

  _dfs(node, prefix, results, maxResults) {
    if (results.length >= maxResults) return;
    if (node.isEndOfWord) results.push(prefix);
    for (const [char, child] of Object.entries(node.children)) {
      this._dfs(child, prefix + char, results, maxResults);
    }
  }
}

// --- Example ---
const trie = new Trie();
['apple', 'app', 'application', 'apt', 'bat', 'ball'].forEach(w => trie.insert(w));

console.log(trie.search('app'));       // true
console.log(trie.search('ap'));        // false
console.log(trie.startsWith('ap'));    // true
console.log(trie.autocomplete('app')); // ['app', 'apple', 'application']

module.exports = { Trie };

import { useState, useEffect, useCallback } from 'react';

interface UseFetchResult<T> {
  data: T | null;
  loading: boolean;
  error: Error | null;
  refetch: () => void;
}

/**
 * useFetch — Generic data fetching hook with loading/error states.
 *
 * @example
 * const { data, loading, error, refetch } = useFetch<User[]>('/api/users');
 */
export function useFetch<T>(url: string, options?: RequestInit): UseFetchResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [trigger, setTrigger] = useState(0);

  const refetch = useCallback(() => setTrigger(t => t + 1), []);

  useEffect(() => {
    const controller = new AbortController();
    let cancelled = false;

    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const response = await fetch(url, {
          ...options,
          signal: controller.signal,
        });
        if (!response.ok) {
          throw new Error(`HTTP ${response.status}: ${response.statusText}`);
        }
        const json = await response.json();
        if (!cancelled) setData(json);
      } catch (err) {
        if (!cancelled && err instanceof Error && err.name !== 'AbortError') {
          setError(err);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    fetchData();
    return () => {
      cancelled = true;
      controller.abort();
    };
  }, [url, trigger]);

  return { data, loading, error, refetch };
}

/**
 * Structured Logger — Production-ready logging utility
 * Features: log levels, timestamps, context, JSON output
 */

const LOG_LEVELS = { debug: 0, info: 1, warn: 2, error: 3 };

class Logger {
  constructor(options = {}) {
    this.level = LOG_LEVELS[options.level || 'info'];
    this.context = options.context || {};
    this.pretty = options.pretty || process.env.NODE_ENV !== 'production';
  }

  _log(level, message, meta = {}) {
    if (LOG_LEVELS[level] < this.level) return;

    const entry = {
      timestamp: new Date().toISOString(),
      level: level.toUpperCase(),
      message,
      ...this.context,
      ...meta,
    };

    if (meta.error instanceof Error) {
      entry.error = {
        name: meta.error.name,
        message: meta.error.message,
        stack: meta.error.stack,
      };
    }

    const output = this.pretty
      ? JSON.stringify(entry, null, 2)
      : JSON.stringify(entry);

    if (level === 'error') {
      console.error(output);
    } else if (level === 'warn') {
      console.warn(output);
    } else {
      console.log(output);
    }
  }

  debug(msg, meta) { this._log('debug', msg, meta); }
  info(msg, meta)  { this._log('info', msg, meta); }
  warn(msg, meta)  { this._log('warn', msg, meta); }
  error(msg, meta) { this._log('error', msg, meta); }

  child(context) {
    return new Logger({
      level: Object.keys(LOG_LEVELS).find(k => LOG_LEVELS[k] === this.level),
      context: { ...this.context, ...context },
      pretty: this.pretty,
    });
  }
}

// --- Usage ---
const logger = new Logger({ level: 'debug', context: { service: 'api' } });
logger.info('Server started', { port: 3000 });

const reqLogger = logger.child({ requestId: 'abc-123' });
reqLogger.info('Processing request', { path: '/users' });
reqLogger.error('Failed', { error: new Error('DB timeout') });

module.exports = { Logger };

/**
 * Promise Patterns & Utilities
 * Practical async patterns for real-world applications.
 */

// 1. Retry with exponential backoff
async function retry(fn, { maxAttempts = 3, baseDelay = 1000 } = {}) {
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === maxAttempts) throw err;
      const delay = baseDelay * Math.pow(2, attempt - 1);
      console.log(`Attempt ${attempt} failed, retrying in ${delay}ms...`);
      await new Promise(r => setTimeout(r, delay));
    }
  }
}

// 2. Promise pool — limit concurrency
async function promisePool(tasks, concurrency = 5) {
  const results = [];
  const executing = new Set();

  for (const [index, task] of tasks.entries()) {
    const p = Promise.resolve().then(() => task()).then(result => {
      results[index] = { status: 'fulfilled', value: result };
    }).catch(error => {
      results[index] = { status: 'rejected', reason: error };
    }).finally(() => executing.delete(p));

    executing.add(p);
    if (executing.size >= concurrency) {
      await Promise.race(executing);
    }
  }

  await Promise.all(executing);
  return results;
}

// 3. Timeout wrapper
function withTimeout(promise, ms, message = 'Operation timed out') {
  const timeout = new Promise((_, reject) =>
    setTimeout(() => reject(new Error(message)), ms)
  );
  return Promise.race([promise, timeout]);
}

// 4. Debounced async function
function debounceAsync(fn, ms) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    return new Promise((resolve) => {
      timer = setTimeout(() => resolve(fn(...args)), ms);
    });
  };
}

module.exports = { retry, promisePool, withTimeout, debounceAsync };
